from collections import defaultdict

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0]); seen=set()
    for r in range(h):
        for c in range(w):
            if g[r][c]==0 or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<h and 0<=b<w and g[a][b]!=0 and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            r0=min(x for x,y in cells); r1=max(x for x,y in cells); c0=min(y for x,y in cells); c1=max(y for x,y in cells)
            depth={}
            for x,y in cells:
                color=g[x][y]; d=min(x-r0,r1-x,y-c0,c1-y)
                depth[color]=min(depth.get(color,10**9),d)
            layers=sorted(depth, key=lambda color: depth[color])
            mapping=dict(zip(layers,reversed(layers)))
            for x,y in cells: g[x][y]=mapping[g[x][y]]
    return g
